    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i + 1;
        var isActive = step == CurrentStep;
        var isCompleted = CompletedSteps.Contains(step);
        var css = isActive ? "step active" : isCompleted ? "step completed" : "step";

        <div class="@css" @onclick="() => OnStepClick(step)">
            <div class="step-circle">
                @if (isCompleted && !isActive)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@step</span>
                }
            </div>
            <div class="step-label">@StepNames[i]</div>
        </div>

        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(isCompleted ? "completed" : "")"></div>
        }
    }
</div>

