{"path": "/tmp/sv-e8e704315ec046cf93d4ec02298ff260/Components/Pages/Apply/Apply.razor", "file_text": "@page "/apply"
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    @if (submittedId is not null)
    {
        <div class="alert alert-success text-center py-4">
            <h4 class="alert-heading">Application Submitted!</h4>
            <p class="mb-0">Your application has been received. Your application ID is <strong>#@submittedId</strong>.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="currentStep" CompletedSteps="completedSteps"
                       OnStepClicked="GoToStep" />

        @switch (currentStep)
        {
            case 1:
                <PersonalInfoStep Model="personalInfo" OnNext="NextStep" />
                break;
            case 2:
                <WorkHistoryStep Entries="workEntries" OnNext="NextStep" OnBack="PreviousStep" />
                break;
            case 3:
                <ReferencesStep References="references" OnNext="NextStep" OnBack="PreviousStep" />
                break;
            case 4:
                <CoverLetterStep @bind-CoverLetter="coverLetter"
                                 OnNext="NextStep" OnBack="PreviousStep" />
                break;
            case 5:
                <ReviewStep Personal="personalInfo" WorkEntries="workEntries"
                            References="references" CoverLetter="coverLetter"
                            IsSubmitting="isSubmitting" ErrorMessage="errorMessage"
                            OnEditStep="GoToStep" OnBack="PreviousStep"
                            OnSubmit="SubmitApplication" />
                break;
        }
    }
</div>

@code {
    private int currentStep = 1;
    private readonly HashSet<int> completedSteps = [];

    private readonly PersonalInfoModel personalInfo = new();
    private readonly List<WorkEntryModel> workEntries = [new()];
    private readonly List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    private int? submittedId;
    private bool isSubmitting;
    private string? errorMessage;

    private void NextStep()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void PreviousStep()
    {
        currentStep--;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private async Task SubmitApplication()
    {
        isSubmitting = true;
        errorMessage = null;

        try
        {
            var application = new JobApplication(
                personalInfo.ToRecord(),
                new WorkHistory(workEntries.Select(e => e.ToRecord()).ToList()),
                references.Select(r => r.ToRecord()).ToList(),
                coverLetter
            );

            submittedId = await ApplicationService.SubmitApplicationAsync(application);
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}
"}

